                SET BudgetAmount = BudgetAmount - @Amount
                WHERE DepartmentID = @FromDeptID;

                UPDATE dbo.Departments
                SET BudgetAmount = BudgetAmount + @Amount
                WHERE DepartmentID = @ToDeptID;

