    FETCH NEXT FROM queue_cursor INTO @QueueID, @EmpID, @Action;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        BEGIN TRY
            BEGIN TRY
                -- Inner validation
                IF NOT EXISTS (SELECT 1 FROM dbo.Employees WHERE EmployeeID = @EmpID)
                    THROW 50020, 'Employee not found for queue item', 1;

                -- Process the action
