    @DepartmentID INT,
    @EmployeeCount INT OUTPUT,
    @TotalSalary DECIMAL(12,2) OUTPUT,
    @AvgSalary DECIMAL(10,2) OUTPUT,
    @MinSalary DECIMAL(10,2) OUTPUT,
    @MaxSalary DECIMAL(10,2) OUTPUT,
