    SELECT
        @DepartmentID AS DepartmentID,
        @EmployeeCount AS EmployeeCount,
        @TotalSalary AS TotalSalary,
        @AvgSalary AS AvgSalary,
        @BudgetRemaining AS BudgetRemaining;
END;

