CREATE PROCEDURE dbo.sp_ProcessQueueWithErrorHandling
    @MaxItems INT = 10,
    @ProcessedCount INT OUTPUT,
    @ErrorCount INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    SET @ProcessedCount = 0;
    SET @ErrorCount = 0;

    DECLARE @QueueID INT;
    DECLARE @EmpID INT;
    DECLARE @Action NVARCHAR(50);

