    @FromDeptID INT,
    @ToDeptID INT,
    @Amount DECIMAL(12,2),
    @ApprovedBy NVARCHAR(128)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        -- Outer TRY: Transaction management
        BEGIN TRANSACTION;

        -- Validate departments exist
