    @EmployeeID INT,
    @NewDepartmentID INT = NULL,
    @SalaryIncrease DECIMAL(5,2) = 10.0,
    @WasPromoted BIT OUTPUT,
    @NewSalary DECIMAL(10,2) OUTPUT,
    @PromotionMessage NVARCHAR(500) OUTPUT
