-- Processes budget transfer with inner validation and outer error handling
-- =============================================================================

CREATE PROCEDURE dbo.sp_NestedTryCatchTransfer
    @FromDeptID INT,
    @ToDeptID INT,
    @Amount DECIMAL(12,2),
    @ApprovedBy NVARCHAR(128)
