            THROW;
        END CATCH;

        COMMIT TRANSACTION;

        SELECT 'Transfer completed successfully' AS Result, @Amount AS TransferredAmount;

    END TRY
    BEGIN CATCH
        -- Outer CATCH: Rollback and log
        IF @@TRANCOUNT > 0
