        SET @ProcessedCount += 1;
        FETCH NEXT FROM emp_cursor INTO @EmpID, @CurrentSalary, @EmpDeptID;
    END;

    CLOSE emp_cursor;
    DEALLOCATE emp_cursor;

    SELECT @ProcessedCount AS EmployeesProcessed, @AdjustmentPercent AS AdjustmentPercent;
END;

