DECLARE
    v_CurrentSalary DECIMAL(10,2);
    v_CurrentDeptID INT;
    v_EmpName TEXT;
    v_TargetDept INT;
    v_DeptBudget DECIMAL(12,2);
    v_DeptCurrentSalaries DECIMAL(12,2);
BEGIN
    -- Initialize output parameters
    p_WasPromoted := 0;
    p_NewSalary := 0;
    p_PromotionMessage := '';

    -- Get employee information
    SELECT Salary, DepartmentID, FirstName || ' ' || LastName
    INTO v_CurrentSalary, v_CurrentDeptID, v_EmpName
    FROM public.Employees 
    WHERE EmployeeID = p_EmployeeID;

    -- Check if employee exists
    IF v_CurrentSalary IS NULL THEN
        p_PromotionMessage := 'Employee not found';
        RETURN;
    END IF;

    -- Calculate new salary
    p_NewSalary := v_CurrentSalary * (1 + p_SalaryIncrease / 100.0);
    v_TargetDept := COALESCE(p_NewDepartmentID, v_CurrentDeptID);

    -- Check budget allows the promotion
    SELECT BudgetAmount 
    INTO v_DeptBudget
    FROM public.Departments 
    WHERE DepartmentID = v_TargetDept;

    SELECT COALESCE(SUM(Salary), 0) 
    INTO v_DeptCurrentSalaries
    FROM public.Employees 
    WHERE DepartmentID = v_TargetDept 
      AND EmployeeID <> p_EmployeeID;

    IF (v_DeptCurrentSalaries + p_NewSalary) > v_DeptBudget THEN
        p_PromotionMessage := 'Promotion denied: would exceed department budget';
        p_NewSalary := v_CurrentSalary;
        RETURN;
    END IF;

    -- Apply promotion
